package org.jetbrains.bazel.utils;

import org.jspecify.annotations.Nullable;

import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public record ExecutableInfo(
    Path binary,
    Path workingDir,
    List<String> args,
    Map<String, String> envVars
) {

    /**
     * Parses the content of the run script generated by `bazel run --script_path` into the {@link ExecutableInfo} needed to
     * attach a native debugger.
     */
    public static ExecutableInfo fromBazelRunScript(String scriptContent) throws UnexpectedScriptContentException, RunfileManifestOnlyException {
        List<String> args = extractArgs(scriptContent);
        Path execRoot = extractExecRoot(scriptContent);
        if (execRoot == null) {
            throw new UnexpectedScriptContentException("Unable to read execution root from script.");
        }
        Path testSrcDir = extractTestSrcDir(scriptContent, execRoot);
        // regular binary case: <executable> [arg0 .. argN] $@
        if (testSrcDir == null) {
            if (args.size() < 2) {
                throw new UnexpectedScriptContentException("Expected at least 2 arguments for regular binary. Actual args: " + args);
            }
            return new ExecutableInfo(
                /* binary = */ Path.of(args.get(0)),
                /* workingDir = */ execRoot,
                /* args = */ List.copyOf(args.subList(1, args.size() - 1)), // drops <executable> and $@
                /* envVars = */ Map.of()
            );
        }
        // test binary case: <wrapper> <executable> [arg0 .. argN] $@
        if (args.size() < 3) {
            throw new UnexpectedScriptContentException("Expected at least 3 arguments for test binary. Actual args: " + args);
        }
        String workspaceName = extractWorkspaceName(scriptContent);
        if (workspaceName == null) {
            throw new UnexpectedScriptContentException("Unable to read workspace name from script.");
        }
        Map<String, String> runfilesEnv = extractRunfilesEnv(scriptContent, execRoot);
        Path runfilesRoot = testSrcDir.resolve(workspaceName);
        String testTarget = extractTestTarget(scriptContent);
        String packagePath = testTarget != null ? testTarget : "";
        Map<String, String> envVars = new LinkedHashMap<>(runfilesEnv);
        envVars.put("TEST_SRCDIR", testSrcDir.toString());
        return new ExecutableInfo(
            /* binary = */ runfilesRoot.resolve(args.get(1)),
            /* workingDir = */ runfilesRoot.resolve(packagePath),
            /* args = */ List.copyOf(args.subList(2, args.size() - 1)), // drops <wrapper> <executable> and $@
            /* envVars = */ envVars
        );
    }

    // Matches TEST_SRCDIR=<dir>
    private static final Pattern TEST_SRCDIR = Pattern.compile("TEST_SRCDIR=(\\S+)");

    // Matches RUNFILES_<NAME>=<value>
    private static final Pattern RUNFILES_VAR = Pattern.compile("RUNFILES_([A-Z_]+)=(\\S+)");

    // Matches TEST_TARGET=//<package_path>:<target>
    private static final Pattern TEST_TARGET = Pattern.compile("TEST_TARGET=//([^:]*):(\\S+)");

    // Matches TEST_WORKSPACE=<name> - the runfiles top-level directory of the main repo (e.g. "_main" with Bzlmod).
    private static final Pattern TEST_WORKSPACE = Pattern.compile("TEST_WORKSPACE=(\\S+)");

    // Matches the `cd <dir> &&` line the generated script uses to enter the Bazel execution root.
    private static final Pattern SCRIPT_BASE_DIR = Pattern.compile("(?m)^\\s*cd (.+?) &&");

    // Matches a space-delimited arg list. Supports wrapping arg in single quotes.
    private static final Pattern ARGS = Pattern.compile("([^\']\\S*|\'.+?\')\\s*");

    // The actual Bazel shell script uses "1", which is considered as true.
    // For robustness, we include other common representations of true.
    private static final List<String> TRUTHY_ENV_VALUES_LOWER = List.of("true", "1", "yes", "on");

    private static List<String> extractArgs(String receiver) {
        String[] lines = receiver.split("\n", -1);
        String lastLine = lines[lines.length - 1].trim();
        List<String> result = new ArrayList<>();
        Matcher matcher = ARGS.matcher(lastLine);
        while (matcher.find()) {
            result.add(trimQuotes(matcher.group(1)));
        }
        return result;
    }

    private static @Nullable Path extractExecRoot(String receiver) {
        Matcher matcher = SCRIPT_BASE_DIR.matcher(receiver);
        if (!matcher.find()) {
            return null;
        }
        return toNioPathOrNull(matcher.group(1).strip());
    }

    private static @Nullable String extractWorkspaceName(String receiver) {
        Matcher matcher = TEST_WORKSPACE.matcher(receiver);
        return matcher.find() ? matcher.group(1) : null;
    }

    private static @Nullable Path extractTestSrcDir(String receiver, Path execRoot) {
        Matcher matcher = TEST_SRCDIR.matcher(receiver);
        return matcher.find() ? execRoot.resolve(matcher.group(1)) : null;
    }

    private static @Nullable String extractTestTarget(String receiver) {
        Matcher matcher = TEST_TARGET.matcher(receiver);
        return matcher.find() ? matcher.group(1) : null;
    }

    private static Map<String, String> extractRunfilesEnv(String receiver, Path execRoot) throws RunfileManifestOnlyException {
        Map<String, String> result = new LinkedHashMap<>();
        Matcher matcher = RUNFILES_VAR.matcher(receiver);
        while (matcher.find()) {
            String key = "RUNFILES_" + matcher.group(1);
            String value = matcher.group(2);
            if (key.equals("RUNFILES_MANIFEST_ONLY") && isTruthyValue(value)) {
                throw new RunfileManifestOnlyException();
            }
            result.put(key, execRoot.resolve(value).toString());
        }
        return result;
    }

    private static boolean isTruthyValue(String receiver) {
        String normalized = receiver.trim().toLowerCase(Locale.getDefault());
        return TRUTHY_ENV_VALUES_LOWER.contains(normalized);
    }

    // consulo: Kotlin String.trim('\'')
    private static String trimQuotes(String value) {
        int start = 0;
        int end = value.length();
        while (start < end && value.charAt(start) == '\'') {
            start++;
        }
        while (end > start && value.charAt(end - 1) == '\'') {
            end--;
        }
        return value.substring(start, end);
    }

    // consulo: IntelliJ String.toNioPathOrNull()
    private static @Nullable Path toNioPathOrNull(String path) {
        try {
            return Path.of(path);
        }
        catch (InvalidPathException e) {
            return null;
        }
    }

    public static class UnexpectedScriptContentException extends Exception {
        public UnexpectedScriptContentException(String reason) {
            super("Failed to parse Bazel run script. Reason: " + reason);
        }
    }

    public static class RunfileManifestOnlyException extends Exception {
        public RunfileManifestOnlyException() {
            super("Detected RUNFILES_MANIFEST_ONLY flag.");
        }
    }
}
